CREATE   VIEW dbo.vw_furniture_discount_profitability  AS  SELECT      Sub_Category,      Discount * 100 AS discount_pct,      SUM(Sales) AS total_sales,      SUM(Profit) AS total_profit,        ROUND(          SUM(Profit) * 100.0 /          NULLIF(SUM(Sales), 0),          2      ) AS profit_margin_pct,        COUNT(*) AS total_rows    FROM dbo.clean_superstore_orders    WHERE Category = 'Furniture'    AND Sub_Category IN ('Tables', 'Bookcases')    GROUP BY      Sub_Category,      Discount;  